		for p < len(guard) && (guard[p] == ' ' || guard[p] == '&') {
			p++
		}
		if p >= len(guard) {
			return true
		}
		want := true
		if guard[p] == '!' {
			want = false
			p++
		}
		start := p
		for p < len(guard) && guard[p] != ' ' && guard[p] != '&' {
			p++
		}
		name := guard[start:p]
		value := false
		for i := range info.Fields {
			f := &info.Fields[i]
			if f.Name == name {
				value = tableJSONGetRaw(unsafe.Add(base, uintptr(f.Offset)), f.ElemSize) != 0
				break
			}
		}
		if value != want {
			return false
		}
