// MixedEntityLoadTolerant is the TOLERANT read (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): it accepts every
// wire the framing walk accepts and keeps the recovered value, with the report's
// counters counted onto the one passed. It refuses only framing damage and a form
// it does not carry. MixedEntityLoad is the strict read; call this one by name.
func MixedEntityLoadTolerant(value *MixedEntity, data []byte, report *TableReport) bool {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, verdict := tableOpen(data, report)
	report.Verdict = verdict
	report.Reason = ""
	if verdict == TableOpenRefused {
		report.Reason = "newer_form"
		if len(data) > 0 {
			if data[0] == 2 {
				report.Reason = "message_form_as_file"
			} else if data[0] == 0 {
				report.Reason = "previous_form"
			}
		}
	}
	if verdict != TableOpenOk {
		MixedEntityReset(value)
		if verdict == TableOpenDamaged {
			report.Malformed = true
		}
		return false
	}
	// The root read answers its own early end after the walk, not before it.
	// A body that returned at its zero reference left the cursor on the byte
	// after that reference. Every field leaves the cursor where skip would, so
	// r.Offset != len(r.Buffer) is the old EndsEarly on the true path.
	// Nothing is decoded on the damaged path: the value goes back to defaults
	// and the report goes back to what the caller handed in, so an early end
	// counts no unknown, no kind mismatch and no clamp — as when the framing
	// walk refused before the reader had seen one byte.
	before := *report
	if !MixedEntityLoadBody(&r, value) || report.NonFiniteFloat != "" {
		if tableNonFiniteRefused(report) {
			MixedEntityReset(value)
			return false
		}
		// The reading walk stops on rules the framing walk has no opinion about
		// — a reserved id in a file body is the one that matters — so a body
		// that stopped is still asked the framing question from the start of
		// the body, and a body whose framing ends early is damage whatever else
		// was wrong with it.
		probe := r
		probe.Offset = 0
		if probe.EndsEarly() {
			MixedEntityReset(value)
			*report = before
			report.Malformed = true
			report.Verdict = TableOpenDamaged
			return false
		}
		report.Verdict = TableOpenBodyStopped
		return false
	}
	if r.Offset != int64(len(r.Buffer)) {
		MixedEntityReset(value)
		*report = before
		report.Malformed = true
		report.Verdict = TableOpenDamaged
		return false
	}
	return true
}

// MixedEntityLoad is the plain read, and it is STRICT (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): it refuses
// whatever MixedEntityReadStrict refuses (malformed, clamped, kind_mismatch, unknown form,
// wire damage, build version, missing_required), resets value to its defaults and
// answers false. A supplied report receives THIS read's report, and on a refusal
// report.Err() is the typed reason. MixedEntityLoadTolerant keeps a recovered value.
func MixedEntityLoad(value *MixedEntity, data []byte, report *TableReport) bool {
	read := report
	if read == nil {
		read = &TableReport{}
	} else {
		*read = TableReport{}
	}
	ok := MixedEntityLoadTolerant(value, data, read)
	if !ok || read.Err() != nil {
		MixedEntityReset(value)
		return false
	}
	return true
}

// MixedEntityReadStrict is the STRICT read (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): one call, one typed reason.
func MixedEntityReadStrict(wire []byte) (*MixedEntity, error) {
	value := &MixedEntity{}
	var report TableReport
	ok := MixedEntityLoadTolerant(value, wire, &report)
	if err := report.Err(); err != nil || !ok {
		if err == nil {
			err = TableRefuseWireDamaged
		}
		return nil, err
	}
	return value, nil
}

// MixedStatReset restores MixedStat's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func MixedStatReset(value *MixedStat) {
	value.StatID = 0
	value.Delta = 0
}

func MixedStatMeasureBody(value *MixedStat, ids *TableIds) int64 {
	bytes := int64(1)
	if (value.StatID != 0) && (value.StatID > 255) {
		return -1
	}
	if value.StatID != 0 {
		bytes += tableLebBytes(ids.refAtHit(38, 0x80ab75f0866dbf65)) + 1 + 1
	} // stat_id
	if (value.Delta != 0) && (value.Delta < -512 || value.Delta > 511) {
		return -1
	}
	if value.Delta != 0 {
		bytes += tableLebBytes(ids.refAtHit(21, 0x52076675ec13a0c1)) + 1 + 4
	} // delta
	if ids.Overflow {
		return -1
	}
	return bytes
}

func MixedStatMeasure(value *MixedStat) int64 {
	var ids TableIds
	body := MixedStatMeasureBody(value, &ids)
	if body < 0 || ids.Overflow {
		return -1
	}
	return 1 + body + int64(ids.Count)*8 + 8
}

func MixedStatMeasureReason(value *MixedStat) (int64, error) {
	size := MixedStatMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
func MixedStatSaveBody(w *TableWriter, value *MixedStat) bool {
	{
		if value.StatID != 0 {
			if ref := w.Ids.refAtHit(38, 0x80ab75f0866dbf65); !w.headerPair(ref, 6) {
				w.headerRest(ref, 6)
			}
			if value.StatID > 255 {
				return false
			}
			w.Put8(uint8(value.StatID))
		}
	}
	{
		if value.Delta != 0 {
			if ref := w.Ids.refAtHit(21, 0x52076675ec13a0c1); !w.headerPair(ref, 4) {
				w.headerRest(ref, 4)
			}
			if value.Delta < -512 || value.Delta > 511 {
				return false
			}
			w.Put32(uint32(value.Delta))
		}
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}

func MixedStatSave(value *MixedStat, buffer []byte) int64 {
	var ids TableIds
	w := TableWriter{Buffer: buffer, Ids: &ids}
	w.Put8(1)
	if !MixedStatSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

